import { FilterForm } from 'models/Filters';
import { WATCH_TOWER_PAGE_NAME } from 'pages/pillars/ValueCreation/WatchTower/constants';

type WatchTowerFilterFieldState = {
  disabled: boolean;
  hidden: boolean;
  placeholder?: string;
};

const BRAND_DEPENDENT_FIELDS = new Set(['region', 'driver', 'channel']);

const VEHICLE_PARENT_KEYS: Record<string, string> = {
  vehicle_level_1: 'driver',
  vehicle_level_2: 'vehicle_level_1',
  vehicle_level_3: 'vehicle_level_2',
  vehicle_level_4: 'vehicle_level_3',
  vehicle_level_5: 'vehicle_level_4',
};

const VEHICLE_VISIBILITY_KEYS: Record<string, string> = {
  vehicle_level_1: 'watch_tower_brand',
  vehicle_level_2: 'vehicle_level_1',
  vehicle_level_3: 'vehicle_level_2',
  vehicle_level_4: 'vehicle_level_3',
  vehicle_level_5: 'vehicle_level_4',
};

export const hasWatchTowerFilterValue = (value: unknown): boolean =>
  value !== null && value !== undefined && value !== '';

export function getWatchTowerVehicleParentKey(
  fieldKey: string,
): string | undefined {
  return VEHICLE_PARENT_KEYS[fieldKey];
}

const parentPlaceholder = (parentKey: string): string => {
  if (parentKey === 'driver') return 'Select a Driver first';
  const level = parentKey.replace('vehicle_level_', '');
  return `Select Vehicle ${level} first`;
};

export function getWatchTowerFilterFieldState(
  pageName: string,
  fieldKey: string,
  values: FilterForm,
): WatchTowerFilterFieldState {
  if (pageName !== WATCH_TOWER_PAGE_NAME) {
    return { disabled: false, hidden: false };
  }

  if (BRAND_DEPENDENT_FIELDS.has(fieldKey)) {
    const disabled = !hasWatchTowerFilterValue(values.watch_tower_brand);
    return {
      disabled,
      hidden: false,
      ...(disabled ? { placeholder: 'Select a Brand first' } : {}),
    };
  }

  const parentKey = VEHICLE_PARENT_KEYS[fieldKey];
  if (!parentKey) {
    return { disabled: false, hidden: false };
  }

  const visibilityKey = VEHICLE_VISIBILITY_KEYS[fieldKey];
  const hidden = !hasWatchTowerFilterValue(values[visibilityKey]);
  const disabled = !hasWatchTowerFilterValue(values[parentKey]);

  return {
    disabled,
    hidden,
    ...(disabled ? { placeholder: parentPlaceholder(parentKey) } : {}),
  };
}
